function solve(n) {
  if (n <= 0) return false;
  for (const p of [2, 3, 5]) while (n % p === 0) n /= p;
  return n === 1;
}

function solve(x) {
  if (x < 2) return x;
  let l = 1, r = x;
  while (l <= r) {
    const m = (l + r) >> 1;
    if (m <= x / m) l = m + 1; else r = m - 1;
  }
  return r;
}

// 方法1: 迭代
function reverseList(head) {
  let prev = null;
  let curr = head;

  while (curr !== null) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }

  return prev;
}

// 方法2: 递归
function reverseListRecursive(head) {
  if (head === null || head.next === null) {
    return head;
  }

  const newHead = reverseListRecursive(head.next);
  head.next.next = head;
  head.next = null;

  return newHead;
}

function solve(height) {
  let l = 0, r = height.length - 1, ans = 0;
  while (l < r) {
    const area = (r - l) * Math.min(height[l], height[r]);
    if (area > ans) ans = area;
    if (height[l] < height[r]) l++; else r--;
  }
  return ans;
}

function solve(nums, target) {
  let l = 0, sum = 0, ans = Infinity;
  for (let r = 0; r < nums.length; r++) {
    sum += nums[r];
    while (sum >= target) {
      ans = Math.min(ans, r - l + 1);
      sum -= nums[l];
      l++;
    }
  }
  return ans === Infinity ? 0 : ans;
}

function twoSum(nums, target) {
  const map = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) {
      return [map.get(complement), i];
    }
    map.set(nums[i], i);
  }
  return [];
}

// 方法1: 动态规划
function climbStairs(n) {
  if (n <= 2) return n;

  const dp = new Array(n + 1);
  dp[1] = 1;
  dp[2] = 2;

  for (let i = 3; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }

  return dp[n];
}

// 方法2: 空间优化
function climbStairs(n) {
  if (n <= 2) return n;

  let prev1 = 2, prev2 = 1;
  for (let i = 3; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }

  return prev1;
}

function removeElements(head, val) {
  // 方法：虚拟头结点
  const dummy = { val: 0, next: head };
  let cur = dummy;
  while (cur.next !== null) {
    if (cur.next.val === val) {
      cur.next = cur.next.next;
    } else {
      cur = cur.next;
    }
  }
  return dummy.next;
}

