function search(nums, target) {
  let low = 0;
  let high = nums.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (nums[mid] === target) return mid;

    // 右半有序
    if (nums[mid] < nums[high]) {
      if (target > nums[mid] && target <= nums[high]) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    } else {
      // 左半有序
      if (target >= nums[low] && target < nums[mid]) {
        high = mid - 1;
      } else {
        low = mid + 1;
      }
    }
  }
  return -1;
}

function isValid(s) {
  const stack = [];
  const map = {
    ')': '(',
    '}': '{',
    ']': '['
  };

  for (const char of s) {
    if (char in map) {
      // 右括号
      if (stack.length === 0 || stack.pop() !== map[char]) {
        return false;
      }
    } else {
      // 左括号
      stack.push(char);
    }
  }

  return stack.length === 0;
}

function solve(nums) {
  const res = new Array(nums.length);
  let l = 0, r = nums.length - 1, p = nums.length - 1;
  while (l <= r) {
    const a = nums[l] * nums[l], b = nums[r] * nums[r];
    if (a > b) { res[p] = a; l++; } else { res[p] = b; r--; }
    p--;
  }
  return res;
}

function merge(nums1, m, nums2, n) {
  let p1 = m - 1;      // nums1 的有效元素末尾
  let p2 = n - 1;     // nums2 的末尾
  let p = m + n - 1;  // nums1 的末尾

  // 从后往前合并
  while (p1 >= 0 && p2 >= 0) {
    if (nums1[p1] > nums2[p2]) {
      nums1[p] = nums1[p1];
      p1--;
    } else {
      nums1[p] = nums2[p2];
      p2--;
    }
    p--;
  }

  // 如果 nums2 还有剩余，直接复制
  while (p2 >= 0) {
    nums1[p] = nums2[p2];
    p2--;
    p--;
  }

  return nums1;
}

function reversePairs(nums) {
  if (nums.length <= 1) return 0;
  const temp = new Array(nums.length);
  return sort(nums, 0, nums.length - 1, temp);
}

function sort(arr, l, r, temp) {
  if (l >= r) return 0;
  const mid = l + Math.floor((r - l) / 2);
  let res = 0;
  res += sort(arr, l, mid, temp);
  res += sort(arr, mid + 1, r, temp);
  if (arr[mid] > arr[mid + 1]) {
    res += merge(arr, l, mid, r, temp);
  }
  return res;
}

function merge(arr, l, mid, r, temp) {
  for (let k = l; k <= r; k++) temp[k] = arr[k];
  let i = l, j = mid + 1, res = 0;
  for (let k = l; k <= r; k++) {
    if (i > mid) { arr[k] = temp[j++]; }
    else if (j > r) { arr[k] = temp[i++]; }
    else if (temp[i] <= temp[j]) { arr[k] = temp[i++]; }
    else {
      res += mid - i + 1;  // 关键：统计逆序对
      arr[k] = temp[j++];
    }
  }
  return res;
}

function topKFrequent(nums, k) {
  // 统计频率
  const freq = new Map();
  for (const num of nums) {
    freq.set(num, (freq.get(num) || 0) + 1);
  }
  // 按频率排序，取前 k 个
  return [...freq.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, k)
    .map(([num]) => num);
}

