}

function solve(nums, k) {
  const n = nums.length;
  k = k % n;
  function rev(a, s, e) { while (s < e) { const t = a[s]; a[s] = a[e]; a[e] = t; s++; e--; } }
  rev(nums, 0, n - 1);
  rev(nums, 0, k - 1);
  rev(nums, k, n - 1);
  return nums;
}

function solve(numbers, target) {
  let l = 0, r = numbers.length - 1;
  while (l < r) {
    const s = numbers[l] + numbers[r];
    if (s === target) return [l + 1, r + 1];
    else if (s < target) l++; else r--;
  }
  return [];
}

function solve(nums) {
  let p0 = 0, p2 = nums.length - 1, i = 0;
  while (i <= p2) {
    if (nums[i] === 0) { const t = nums[p0]; nums[p0] = nums[i]; nums[i] = t; p0++; i++; }
    else if (nums[i] === 2) { const t = nums[p2]; nums[p2] = nums[i]; nums[i] = t; p2--; }
    else i++;
  }
