function solve(nums) {
  const n = nums.length;
  let i = n - 2;
  while (i >= 0 && nums[i] >= nums[i + 1]) i--;
  if (i >= 0) {
    let j = n - 1;
    while (nums[j] <= nums[i]) j--;
    const t = nums[i]; nums[i] = nums[j]; nums[j] = t;
  }
  let l = i + 1, r = n - 1;
  while (l < r) { const t = nums[l]; nums[l] = nums[r]; nums[r] = t; l++; r--; }
  return nums;
}

function solve(s) {
  let l = 0, r = s.length - 1;
  while (l < r) {
    while (l < r && !/[a-z0-9]/i.test(s[l])) l++;
    while (l < r && !/[a-z0-9]/i.test(s[r])) r--;
    if (s[l].toLowerCase() !== s[r].toLowerCase()) return false;
    l++; r--;
  }
  return true;
}

function solve(strs) {
  if (!strs.length) return "";
  let prefix = strs[0];
  for (let i = 1; i < strs.length; i++) {
    let j = 0;
    while (j < prefix.length && j < strs[i].length && prefix[j] === strs[i][j]) j++;
    prefix = prefix.slice(0, j);
    if (!prefix) return "";
  }
  return prefix;
}

function solve(haystack, needle) {
  if (needle === "") return 0;
  for (let i = 0; i <= haystack.length - needle.length; i++) {
    let j = 0;
    while (j < needle.length && haystack[i + j] === needle[j]) j++;
    if (j === needle.length) return i;
  }
  return -1;
}

function solve(s) {
  if (!s) return "";
  let start = 0, maxLen = 1;
  function expand(l, r) {
    while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }
    const len = r - l - 1;
    if (len > maxLen) { maxLen = len; start = l + 1; }
  }
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i + 1); }
  return s.slice(start, start + maxLen);
}

function solve(strs) {
  const map = {};
  for (const s of strs) {
    const key = s.split("").sort().join("");
    if (!map[key]) map[key] = [];
    map[key].push(s);
  }
  return Object.values(map);
}

function solve(s, t) {
  if (s.length !== t.length) return false;
  const cnt = {};
  for (const c of s) cnt[c] = (cnt[c] || 0) + 1;
  for (const c of t) { if (!cnt[c]) return false; cnt[c]--; }
  return true;
}

function solve(a, b) {
  let i = a.length - 1, j = b.length - 1, carry = 0, res = "";
  while (i >= 0 || j >= 0 || carry) {
    const x = i >= 0 ? +a[i] : 0;
    const y = j >= 0 ? +b[j] : 0;
    const sum = x + y + carry;
    res = (sum % 2) + res;
    carry = Math.floor(sum / 2);
    i--; j--;
  }
  return res;
}

function solve(num) {
  const vals = [1000,900,500,400,100,90,50,40,10,9,5,4,1];
  const syms = ["M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"];
