}

function solve(path) {
  const parts = path.split("/");
  const stack = [];
  for (const p of parts) {
    if (p === "" || p === ".") continue;
    if (p === "..") { stack.pop(); }
    else stack.push(p);
  }
  return "/" + stack.join("/");
}

