}

function solve(pattern, s) {
  const words = s.split(" ");
  if (pattern.length !== words.length) return false;
  const p2w = {}, w2p = {};
  for (let i = 0; i < pattern.length; i++) {
    const p = pattern[i], w = words[i];
    if (p2w[p] && p2w[p] !== w) return false;
    if (w2p[w] && w2p[w] !== p) return false;
    p2w[p] = w; w2p[w] = p;
  }
  return true;
}

function solve(nums) {
