function solve(head, pos) {
  if (pos < 0) return false;
  const list = buildList(head);
  // 构造环
  let tail = list, entry = null, idx = 0, cur = list;
  while (cur && cur.next) { cur = cur.next; idx++; }
  tail = cur; cur = list; idx = 0;
  while (cur) { if (idx === pos) entry = cur; cur = cur.next; idx++; }
  if (entry) tail.next = entry;
  let slow = list, fast = list;
  while (fast && fast.next) { slow = slow.next; fast = fast.next.next; if (slow === fast) return true; }
  return false;
}

