  const la = buildList(a), lb = buildList(b);
  let pa = la, pb = lb, cur = la, k = 0;
  while (cur) { if (k === skipA) { const c = cur; let q = lb, m = 0; while (q) { if (m === skipB) { c.next = q; break; } q = q.next; m++; } break; } cur = cur.next; k++; }
  let x = la, y = lb;
