function solve(head) {
  const list = buildList(head);
  let slow = list, fast = list;
  while (fast && fast.next) { slow = slow.next; fast = fast.next.next; }
  let prev = null, cur = slow;
  while (cur) { const nxt = cur.next; cur.next = prev; prev = cur; cur = nxt; }
  let p = list, q = prev;
  while (q) { if (p.val !== q.val) return false; p = p.next; q = q.next; }
  return true;
}

function solve(head, x) {
  const list = buildList(head);
  const small = { val: 0, next: null }, large = { val: 0, next: null };
  let s = small, l = large, cur = list;
