  const res = [];
  let start = 0, end = 0;
  for (let i = 0; i < s.length; i++) {
    end = Math.max(end, last[s[i]]);
    if (i === end) { res.push(end - start + 1); start = end + 1; }
  }
  return res;
}

function solve(ratings) {
  const n = ratings.length;
  const left = new Array(n).fill(1);
  for (let i = 1; i < n; i++) if (ratings[i] > ratings[i - 1]) left[i] = left[i - 1] + 1;
  let right = 1, sum = 0;
  for (let i = n - 1; i >= 0; i--) {
    if (i < n - 1 && ratings[i] > ratings[i + 1]) right++; else right = 1;
    sum += Math.max(left[i], right);
  }
  return sum;
}

function solve(ops) {
  const set = new Set();
  const res = [];
  for (const op of ops) {
    if (op[0] === "insert") { set.add(op[1]); res.push(null); }
    else if (op[0] === "remove") { set.delete(op[1]); res.push(null); }
    else if (op[0] === "contains") res.push(set.has(op[1]));
  }
  return res;
}

function solve(ops) {
  const root = {};
  function insert(w) { let node = root; for (const ch of w) { if (!node[ch]) node[ch] = {}; node = node[ch]; } node._end = true; }
  function search(w) { let node = root; for (const ch of w) { if (!node[ch]) return false; node = node[ch]; } return !!node._end; }
  function startsWith(p) { let node = root; for (const ch of p) { if (!node[ch]) return false; node = node[ch]; } return true; }
  const res = [];
  for (const op of ops) {
    if (op[0] === "insert") { insert(op[1]); res.push(null); }
    else if (op[0] === "search") res.push(search(op[1]));
    else if (op[0] === "startsWith") res.push(startsWith(op[1]));
  }
  return res;
}
